import React, { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from "react-router-dom";
import api from "./services/api";

const storageTokenKey = "medical_store_token";

const Navigation = ({ user, onLogout }) => (
  <div style={{ marginBottom: 20 }}>
    <Link to="/" style={{ marginRight: 10 }}>Home</Link>
    <Link to="/medicines" style={{ marginRight: 10 }}>Medicines</Link>
    <Link to="/cart" style={{ marginRight: 10 }}>Cart</Link>
    <Link to="/orders" style={{ marginRight: 10 }}>Orders</Link>
    <Link to="/upload" style={{ marginRight: 10 }}>Upload Prescription</Link>
    {user?.role === "admin" && <Link to="/admin" style={{ marginRight: 10 }}>Admin</Link>}
    {user ? <button onClick={onLogout}>Logout</button> : <Link to="/login">Login</Link>}
  </div>
);

function Home() {
  return (
    <div>
      <h1>Online Medical Store</h1>
      <p>Welcome to your online pharmacy management system.</p>
    </div>
  );
}

function Login({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [msg, setMsg] = useState("");
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post("/auth/login", { email, password });
      const token = res.data.token;
      localStorage.setItem(storageTokenKey, token);
      api.defaults.headers.common["Authorization"] = `Bearer ${token}`;
      onLogin(res.data.user);
      navigate("/");
    } catch (err) {
      setMsg(err.response?.data?.msg || "Login failed");
    }
  };

  return (
    <div>
      <h2>Login</h2>
      <form onSubmit={handleSubmit}>
        <div><input placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} /></div>
        <div><input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} /></div>
        <button type="submit">Login</button>
      </form>
      <p style={{ color: "red" }}>{msg}</p>
      <p>Go to <Link to="/register">Register</Link></p>
    </div>
  );
}

function Register() {
  const [form, setForm] = useState({ name: "", email: "", phone: "", password: "", role: "patient" });
  const [msg, setMsg] = useState("");
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post("/auth/register", form);
      setMsg("Registered successfully, please login.");
      setTimeout(() => navigate("/login"), 800);
    } catch (err) {
      setMsg(err.response?.data?.msg || "Registration failed");
    }
  };

  return (
    <div>
      <h2>Register</h2>
      <form onSubmit={handleSubmit}>
        <div><input placeholder="Name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
        <div><input placeholder="Email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></div>
        <div><input placeholder="Phone" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} /></div>
        <div><input type="password" placeholder="Password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} /></div>
        <button type="submit">Register</button>
      </form>
      <p style={{ color: "red" }}>{msg}</p>
    </div>
  );
}

function Medicines({ setCart }) {
  const [medicines, setMedicines] = useState([]);
  const [q, setQ] = useState("");
  const [msg, setMsg] = useState("");

  const load = async () => {
    const res = await api.get(`/medicines${q ? `?q=${encodeURIComponent(q)}` : ""}`);
    setMedicines(res.data);
  };

  useEffect(() => { load(); }, []);

  const addToCart = (med) => {
    setCart((prev) => {
      const existing = prev.find((i) => i.id === med.id);
      if (existing) return prev.map((i) => (i.id === med.id ? { ...i, quantity: i.quantity + 1 } : i));
      return [...prev, { id: med.id, name: med.name, price: med.price, quantity: 1 }];
    });
    setMsg("Added to cart");
  };

  return (
    <div>
      <h2>Medicines</h2>
      <div>
        <input placeholder="Search" value={q} onChange={(e) => setQ(e.target.value)} />
        <button onClick={load}>Search</button>
      </div>
      {msg && <p>{msg}</p>}
      <ul>
        {medicines.map((m) => (
          <li key={m.id}>
            {m.name} ({m.brand}) - ${m.price} - stock {m.stock} - {m.prescription_required ? "Prescription" : "OTC"}
            <button onClick={() => addToCart(m)} style={{ marginLeft: 10 }}>Add to cart</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

function Cart({ cart, setCart }) {
  const [msg, setMsg] = useState("");

  const submitOrder = async () => {
    if (cart.length === 0) { setMsg("Cart is empty"); return; }
    const items = cart.map((i) => ({ id: i.id, quantity: i.quantity, price: i.price }));
    const total = cart.reduce((sum, i) => sum + i.price * i.quantity, 0);
    try {
      await api.post("/orders/create", { items, total, payment_mode: "Cash on delivery" });
      setMsg("Order placed");
      setCart([]);
    } catch (err) {
      setMsg(err.response?.data?.msg || "Order failed");
    }
  };

  return (
    <div>
      <h2>Cart</h2>
      <ul>
        {cart.map((item) => (
          <li key={item.id}>{item.name} x {item.quantity} = ${item.price * item.quantity}</li>
        ))}
      </ul>
      <button onClick={submitOrder}>Place Order</button>
      <p>{msg}</p>
    </div>
  );
}

function Orders() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    api.get("/orders/history").then((res) => setOrders(res.data)).catch(() => setOrders([]));
  }, []);

  return (
    <div>
      <h2>Order History</h2>
      <ul>
        {orders.map((o) => <li key={o.id}>{o.order_id} | {o.status} | ${o.total} | {o.payment_mode}</li>)}
      </ul>
    </div>
  );
}

function UploadPrescription() {
  const [file, setFile] = useState(null);
  const [msg, setMsg] = useState("");

  const submit = async () => {
    if (!file) { setMsg("Select a file"); return; }
    const form = new FormData();
    form.append("file", file);
    try {
      await api.post("/prescriptions/upload", form, { headers: { "Content-Type": "multipart/form-data" } });
      setMsg("Uploaded");
    } catch (err) {
      setMsg(err.response?.data?.msg || "Upload failed");
    }
  };

  return (
    <div>
      <h2>Upload Prescription</h2>
      <input type="file" onChange={(e) => setFile(e.target.files[0])} />
      <button onClick={submit}>Upload</button>
      <p>{msg}</p>
    </div>
  );
}

function Admin() {
  const [medicines, setMedicines] = useState([]);
  const [msg, setMsg] = useState("");

  const load = async () => {
    const res = await api.get("/medicines");
    setMedicines(res.data);
  };

  useEffect(() => { load(); }, []);

  const add = async () => {
    try {
      await api.post("/medicines/add", { name: "Sample Med", brand: "Brand", category: "OTC", price: 5.0, stock: 20, expiry_date: "2026-12-31", prescription_required: false });
      setMsg("Added");
      load();
    } catch (err) {
      setMsg("Add failed");
    }
  };

  return (
    <div>
      <h2>Admin Dashboard</h2>
      <button onClick={add}>Add sample medicine</button>
      <p>{msg}</p>
      <ul>{medicines.map((m) => <li key={m.id}>{m.name} - stock {m.stock}</li>)}</ul>
    </div>
  );
}

function App() {
  const [user, setUser] = useState(null);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem(storageTokenKey);
    if (token) {
      // token validate by API call
      api.get("/users/me", { headers: { Authorization: `Bearer ${token}` } })
        .then((res) => {
          setUser(res.data);
          api.defaults.headers.common["Authorization"] = `Bearer ${token}`;
        })
        .catch(() => {
          localStorage.removeItem(storageTokenKey);
        });
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem(storageTokenKey);
    setUser(null);
    delete api.defaults.headers.common["Authorization"];
  };

  return (
    <Router>
      <div style={{ padding: 20, fontFamily: "Arial, sans-serif" }}>
        <Navigation user={user} onLogout={handleLogout} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login onLogin={setUser} />} />
          <Route path="/register" element={<Register />} />
          <Route path="/medicines" element={<Medicines setCart={setCart} />} />
          <Route path="/cart" element={<Cart cart={cart} setCart={setCart} />} />
          <Route path="/orders" element={<Orders />} />
          <Route path="/upload" element={<UploadPrescription />} />
          <Route path="/admin" element={<Admin />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
